var m=new Intl.DateTimeFormat("en-US",{month:"short",day:"numeric",year:"numeric"}),u=new Intl.DateTimeFormat("en-US",{month:"short",day:"numeric"});function a(t){if(!t)return null;let e=/^\d{4}-\d{2}-\d{2}$/.test(t)?new Date(`${t}T00:00:00`):new Date(t);return Number.isNaN(e.getTime())?null:e}function c(t){let e=a(t);return e?m.format(e):""}function d(t){let e=a(t);return e?u.format(e):""}function f(t,e=Date.now()){let n=a(t);if(!n)return "";let i=Math.max(0,Math.floor((e-n.getTime())/1e3));if(i<45)return "Updated just now";let r=Math.floor(i/60);if(r<60)return `Updated ${r} min ago`;let o=Math.floor(r/60);return o<24?`Updated ${o} hr${o===1?"":"s"} ago`:`Updated ${c(t)}`}function h(t,e=120){let n=t.trim();return n.length>e?`${n.slice(0,e-1).trimEnd()}\u2026`:n}function l(t){return t?.map(e=>e.name).filter(Boolean).join(", ")??""}function p(t){return t?.map(e=>e.key).filter(Boolean).join(", ")??""}export{c,d,f,h,l,p};